1	import { db } from "./db";
2	import type { Prisma } from "@prisma/client";
3	
4	/**
5	 * IPAM — private-IP and SSH-forward-port allocation.
6	 *
7	 * Node-aware: when a `nodeId` is supplied the pool is taken from that Node's
8	 * configured range (`subnetPrefix` / `ipStart` / `ipEnd` / `sshPortStart` /
9	 * `sshPortEnd`). Without a nodeId we fall back to the global env range, which is
10	 * the single-node behaviour this module has always had.
11	 *
12	 * Race safety: `Server.ipAddress` and `Server.sshPort` are UNIQUE columns, so a
13	 * concurrent double-provision must not hand out the same value twice. When the
14	 * caller passes the server it is allocating for, the "find free + claim" pair
15	 * runs inside a single transaction guarded by a Postgres advisory lock, with a
16	 * retry loop on unique-constraint conflicts. Callers that do not pass a server
17	 * id get a best-effort pick plus a short-lived in-process reservation (which
18	 * covers concurrent jobs inside one worker process, the common case).
19	 */
20	
21	const ENV_SUBNET_PREFIX = process.env.NXEON_SUBNET_PREFIX ?? "10.20.0.";
22	const IP_START = Number(process.env.NXEON_IP_START ?? 100);
23	const IP_END = Number(process.env.NXEON_IP_END ?? 250);
24	export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
25	export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);
26	
27	/** Advisory-lock key that serialises IPAM allocation across processes. */
28	const IPAM_LOCK_KEY = 728_144_301;
29	/** How many times we re-pick after losing a unique-constraint race. */
30	const CLAIM_ATTEMPTS = 8;
31	/** How long an unclaimed hand-out is remembered in this process. */
32	const RESERVATION_TTL_MS = 10 * 60_000;
33	
34	export type IpamRange = {
35	  nodeId: string | null;
36	  subnetPrefix: string;
37	  ipStart: number;
38	  ipEnd: number;
39	  sshPortStart: number;
40	  sshPortEnd: number;
41	  bridge: string | null;
42	  natChain: string | null;
43	};
44	
45	const GLOBAL_RANGE: IpamRange = {
46	  nodeId: null,
47	  subnetPrefix: ENV_SUBNET_PREFIX,
48	  ipStart: IP_START,
49	  ipEnd: IP_END,
50	  sshPortStart: SSH_PORT_START,
51	  sshPortEnd: SSH_PORT_END,
52	  bridge: process.env.NXEON_BRIDGE ?? null,
53	  natChain: process.env.NXEON_NAT_CHAIN ?? null,
54	};
55	
56	const num = (v: unknown, fallback: number) =>
57	  typeof v === "number" && Number.isFinite(v) ? v : fallback;
58	
59	/**
60	 * Resolve the pool a node allocates from. Unknown/empty node fields fall back to
61	 * the global env values so a half-configured Node row can never produce an
62	 * empty range.
63	 */
64	export async function ipamRange(nodeId?: string | null): Promise<IpamRange> {
65	  if (!nodeId) return { ...GLOBAL_RANGE };
66	  const node = await db.node.findUnique({
67	    where: { id: nodeId },
68	    select: {
69	      id: true,
70	      subnetPrefix: true,
71	      ipStart: true,
72	      ipEnd: true,
73	      sshPortStart: true,
74	      sshPortEnd: true,
75	      bridge: true,
76	      natChain: true,
77	    },
78	  });
79	  if (!node) return { ...GLOBAL_RANGE };
80	  const prefix = node.subnetPrefix?.trim() || GLOBAL_RANGE.subnetPrefix;
81	  return {
82	    nodeId: node.id,
83	    subnetPrefix: prefix.endsWith(".") ? prefix : `${prefix}.`,
84	    ipStart: num(node.ipStart, GLOBAL_RANGE.ipStart),
85	    ipEnd: num(node.ipEnd, GLOBAL_RANGE.ipEnd),
86	    sshPortStart: num(node.sshPortStart, GLOBAL_RANGE.sshPortStart),
87	    sshPortEnd: num(node.sshPortEnd, GLOBAL_RANGE.sshPortEnd),
88	    bridge: node.bridge ?? GLOBAL_RANGE.bridge,
89	    natChain: node.natChain ?? GLOBAL_RANGE.natChain,
90	  };
91	}
92	
93	// ---------- in-process reservations ----------
94	
95	const reservations = new Map<string, number>();
96	
97	function isReserved(key: string): boolean {
98	  const until = reservations.get(key);
99	  if (until === undefined) return false;
100	  if (until <= Date.now()) {
101	    reservations.delete(key);
102	    return false;
103	  }
104	  return true;
105	}
106	
107	function reserve(key: string): void {
108	  if (reservations.size > 5000) {
109	    const now = Date.now();
110	    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
111	  }
112	  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
113	}
114	
115	function isUniqueConflict(e: any): boolean {
116	  return e?.code === "P2002";
117	}
118	
119	type Tx = Prisma.TransactionClient;
120	
121	/**
122	 * Serialise allocators across processes with a transaction-scoped advisory lock
123	 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
124	 * transaction — a failing statement inside an open Postgres transaction would
125	 * abort it, so we never speculatively try it in the hot path.
126	 */
127	let advisoryLocks: boolean | null = null;
128	// Two workarounds baked in:
129	//  - the key is a literal, not a bound parameter: a bound JS number can reach
130	//    Postgres as `numeric` and fail to resolve the ...(bigint) overload;
131	//  - pg_advisory_xact_lock() returns `void`, which Prisma's $queryRaw cannot
132	//    deserialize, so it is wrapped in a subselect that yields an int column.
133	const LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})) _lock`;
134	
135	async function lockIpam(tx: Tx): Promise<void> {
136	  if (advisoryLocks === false) return;
137	  await tx.$queryRawUnsafe(LOCK_SQL);
138	}
139	
140	async function probeAdvisoryLocks(): Promise<void> {
141	  if (advisoryLocks !== null) return;
142	  try {
143	    // Take and immediately release it (xact locks drop at commit). Done once,
144	    // outside the hot path, because a failing statement inside an open
145	    // transaction would abort that transaction.
146	    await db.$transaction(async (tx) => {
147	      await tx.$queryRawUnsafe(LOCK_SQL);
148	    });
149	    advisoryLocks = true;
150	  } catch {
151	    // Not Postgres, or the role lacks permission: the unique-conflict retry
152	    // loop plus in-process reservations remain as the safety net.
153	    advisoryLocks = false;
154	  }
155	}
156	
157	// ---------- IP allocation ----------
158	
159	/**
160	 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
161	 * same subnet prefix can conflict — servers on other nodes (different prefix)
162	 * are naturally excluded. We still read the column globally because
163	 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
164	 * happens to hold is what keeps the insert from blowing up.
165	 */
166	async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
167	  const rows = await tx.server.findMany({
168	    where: { ipAddress: { startsWith: range.subnetPrefix } },
169	    select: { ipAddress: true },
170	  });
171	  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
172	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
173	    const ip = `${range.subnetPrefix}${i}`;
174	    if (used.has(ip)) continue;
175	    if (isReserved(`ip:${ip}`)) continue;
176	    return ip;
177	  }
178	  throw new Error(
179	    range.nodeId
180	      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
181	      : "IP pool exhausted"
182	  );
183	}
184	
185	/**
186	 * Allocate a private IP.
187	 *
188	 * @param nodeId          allocate from this Node's configured subnet/range.
189	 * @param claimForServerId when given, the IP is written onto that Server row in
190	 *                         the same transaction, making the allocation atomic.
191	 */
192	export async function allocateIp(
193	  nodeId?: string | null,
194	  claimForServerId?: string | null
195	): Promise<string> {
196	  const range = await ipamRange(nodeId);
197	  await probeAdvisoryLocks();
198	
199	  if (!claimForServerId) {
200	    // No row to claim against: pick + reserve in-process so concurrent jobs in
201	    // this worker cannot be handed the same address.
202	    const ip = await db.$transaction(async (tx) => {
203	      await lockIpam(tx);
204	      return pickFreeIp(tx, range);
205	    });
206	    reserve(`ip:${ip}`);
207	    return ip;
208	  }
209	
210	  let lastErr: unknown;
211	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
212	    let ip = "";
213	    try {
214	      ip = await db.$transaction(async (tx) => {
215	        await lockIpam(tx);
216	        const candidate = await pickFreeIp(tx, range);
217	        await tx.server.update({
218	          where: { id: claimForServerId },
219	          data: { ipAddress: candidate },
220	        });
221	        return candidate;
222	      });
223	    } catch (e) {
224	      lastErr = e;
225	      if (isUniqueConflict(e)) {
226	        // Someone beat us to it between pick and claim — skip it and retry.
227	        continue;
228	      }
229	      throw e;
230	    }
231	    reserve(`ip:${ip}`);
232	    return ip;
233	  }
234	  throw new Error(
235	    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
236	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
237	  );
238	}
239	
240	// ---------- SSH forward-port allocation ----------
241	
242	/**
243	 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
244	 * taken-set is read globally even though the *range* we scan is per-node.
245	 * Node-awareness therefore comes from the range: give each node a disjoint
246	 * sshPortStart/sshPortEnd window and two nodes can never collide.
247	 */
248	async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
249	  const [servers, forwards] = await Promise.all([
250	    tx.server.findMany({
251	      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
252	      select: { sshPort: true },
253	    }),
254	    tx.portForward.findMany({
255	      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
256	      select: { publicPort: true },
257	    }),
258	  ]);
259	  const used = new Set<number>([
260	    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
261	    ...forwards.map((f) => f.publicPort),
262	  ]);
263	  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
264	    if (used.has(p)) continue;
265	    if (isReserved(`port:${p}`)) continue;
266	    return p;
267	  }
268	  throw new Error(
269	    range.nodeId
270	      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
271	      : "SSH port pool exhausted"
272	  );
273	}
274	
275	/**
276	 * Allocate an SSH forward port.
277	 *
278	 * @param nodeId          allocate from this Node's configured port range.
279	 * @param claimForServerId when given, the port is written onto that Server row
280	 *                         in the same transaction, making it atomic.
281	 */
282	export async function allocateSshPort(
283	  nodeId?: string | null,
284	  claimForServerId?: string | null
285	): Promise<number> {
286	  const range = await ipamRange(nodeId);
287	  await probeAdvisoryLocks();
288	
289	  if (!claimForServerId) {
290	    const port = await db.$transaction(async (tx) => {
291	      await lockIpam(tx);
292	      return pickFreePort(tx, range);
293	    });
294	    reserve(`port:${port}`);
295	    return port;
296	  }
297	
298	  let lastErr: unknown;
299	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
300	    let port = 0;
301	    try {
302	      port = await db.$transaction(async (tx) => {
303	        await lockIpam(tx);
304	        const candidate = await pickFreePort(tx, range);
305	        await tx.server.update({
306	          where: { id: claimForServerId },
307	          data: { sshPort: candidate },
308	        });
309	        return candidate;
310	      });
311	    } catch (e) {
312	      lastErr = e;
313	      if (isUniqueConflict(e)) continue;
314	      throw e;
315	    }
316	    reserve(`port:${port}`);
317	    return port;
318	  }
319	  throw new Error(
320	    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
321	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
322	  );
323	}
324	
325	/**
326	 * Auto-forward a game's own port at provision time, from the SAME pool and
327	 * under the SAME advisory lock as SSH ports (they've always shared one range
328	 * — see pickFreePort, which already checks both Server.sshPort AND
329	 * PortForward.publicPort). Without this, a NAT (non-dedicated-IP) game
330	 * server's game port was reachable by nobody until the customer manually
331	 * added a forward from the dashboard — found live via a real customer whose
332	 * Minecraft server had zero forwards and no dedicated IP, so its game port
333	 * had no path from any public IP at all. Dedicated-IP servers need no
334	 * forward (their guest port IS the public port) — callers should only call
335	 * this for the NAT case.
336	 */
337	export async function allocateGameForward(
338	  nodeId: string | null | undefined,
339	  serverId: string,
340	  guestPort: number,
341	  protocol: "tcp" | "udp" = "tcp"
342	): Promise<number> {
343	  const range = await ipamRange(nodeId);
344	  await probeAdvisoryLocks();
345	
346	  let lastErr: unknown;
347	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
348	    let port = 0;
349	    try {
350	      port = await db.$transaction(async (tx) => {
351	        await lockIpam(tx);
352	        const candidate = await pickFreePort(tx, range);
353	        await tx.portForward.create({
354	          data: { serverId, publicPort: candidate, guestPort, protocol },
355	        });
356	        return candidate;
357	      });
358	    } catch (e) {
359	      lastErr = e;
360	      if (isUniqueConflict(e)) continue;
361	      throw e;
362	    }
363	    reserve(`port:${port}`);
364	    return port;
365	  }
366	  throw new Error(
367	    `Game port forward allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
368	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
369	  );
370	}
371	
372	// ---------- gateway ----------
373	
374	/**
375	 * Gateway for a NAT subnet. Backwards compatible: called with no argument it
376	 * returns the global gateway exactly as before. Pass a Node's `subnetPrefix`
377	 * (or use {@link gatewayIpForNode}) for multi-node correctness.
378	 */
379	export function gatewayIp(subnetPrefix?: string | null): string {
380	  const prefix = subnetPrefix?.trim() || ENV_SUBNET_PREFIX;
381	  return `${prefix.endsWith(".") ? prefix : `${prefix}.`}1`;
382	}
383	
384	/** Async node-aware variant of {@link gatewayIp}. */
385	export async function gatewayIpForNode(nodeId?: string | null): Promise<string> {
386	  const range = await ipamRange(nodeId);
387	  return gatewayIp(range.subnetPrefix);
388	}
389

480	  // keeps the vmid already persisted on the row.
481	  const vmid = server.vmid ?? (await allocateFreshVmid(conn));
482	
483	  // The password must be generated ONCE per VM, not once per attempt. cloud-init's
484	  // cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
485	  // cipassword was baked into the FIRST boot's snippet and never re-applies on a
486	  // later config change unless the guest gets a brand-new instance-id. A retried
487	  // PROVISION (server.vmid already set = the clone below is skipped as
488	  // `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
489	  // again anyway and overwrite Server.rootPasswordEnc with a value the running VM
490	  // never saw — every later SSH from the platform (control panel, GAME_POWER,
491	  // mods, backups) then authenticated with a password that does not match
492	  // /etc/shadow on the guest, failing with "All configured authentication methods
493	  // failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
494	  // logins ever, until the guest's password was force-resynced via the QGA
495	  // set-user-password path). Reuse the already-stored password whenever this
496	  // server already has a vmid (meaning some earlier attempt may have already
497	  // cloned + booted it); only a truly first attempt mints a new one.
498	  const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();
499	
500	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
501	  // VPS: the global `dedicated_ip_default` setting acts as a platform-wide default (included
502	  // on every plan unless the admin switches it off). Game servers: the customer must
503	  // explicitly purchase the addon at checkout — game orders set `wantsDedicatedIp` from the
504	  // intent, so the global default must NOT override it (that was silently granting free IPs).
505	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
506	  const { getSettingBool: _settingBool } = await import("../lib/settings");
507	  const isGame = !!server.gamePlanId;
508	  const wantDedicated = isGame
509	    ? server.wantsDedicatedIp
510	    : server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
511	  if (wantDedicated && ovhConfigured()) {
512	    try {
513	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
514	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
515	      dedicated = await allocateDedicatedIp(server.id, vmid);
516	    } catch (e) {
517	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
518	    }
519	  }
520	  // Node-aware + transactionally-claimed allocation (passing the server id enables
521	  // the claim path, so two concurrent provisions can't pick the same IP/port).
522	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
523	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
524	
525	  await db.server.update({
526	    where: { id: server.id },
527	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
528	  });
529	
530	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
531	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
532	  // (worker restart mid-clone, or any transient failure in the steps below) would
533	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
534	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
535	  // the clone is idempotent, so skip it when the VM is already present.
536	  let vmAlreadyExists = false;
537	  try {
538	    await conn.vmStatus(vmid);
539	    vmAlreadyExists = true;
540	  } catch {
541	    vmAlreadyExists = false;
542	  }
543	  if (vmAlreadyExists) {
544	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
545	  } else {
546	    await step("Allocating your server…");
547	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
548	      newid: vmid,
549	      name: server.hostname,
550	      full: 1,
551	      storage,
552	    });
553	    await conn.waitForTask(cloneUpid, 600_000);
554	  }
555	
556	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
557	  //
558	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
559	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
560	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
561	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
562	  // all silently vanish, and the customer is still told the server is ready.
563	  // Failing here is recoverable — the job retries, and the clone above is
564	  // idempotent. Continuing is not.
565	  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
566	  // generate its one-time admin password (persisted, once) and get the idempotent
567	  // install script to bake into cloud-init. Null for an ordinary VPS.
568	  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
569	  // Live telemetry: mint a fresh per-server shipper token and persist its hash
570	  // BEFORE building cloud-init, so the config the agent boots with matches what
571	  // the ingest route will look up (lib/telemetry-token.ts). Re-provisioning
572	  // (this code path runs again) simply mints a new token, invalidating the old
573	  // one — no rotation UI needed for that case.
574	  (server as any).__telemetryToken = await mintServerTelemetryToken(server.id);
575	
576	  await step("Configuring the network…");
577	  const snippet = buildCloudInit(server);
578	  try {
579	    await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8");
580	  } catch (e: any) {
581	    throw new Error(
582	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
583	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
584	        `stopped here rather than reporting a server that would not be usable.`
585	    );
586	  }
587	
588	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
589	  const sshkeys = keys.length
590	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
591	    : undefined;
592	  const cfg: Record<string, any> = {
593	    cores: server.plan.cpuCores,
594	    memory: server.plan.ramMB,
595	    ciuser: "root",
596	    cipassword: password,
597	    sshkeys,
598	    nameserver: "1.1.1.1 8.8.8.8",
599	    onboot: 1,
600	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
601	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
602	  };
603	  if (dedicated) {
604	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
605	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
606	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
607	  } else {
608	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
609	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
610	  }
611	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
612	
613	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
614	  // customer bought as a deploy-time upsell, so the VM is born the right size and
615	  // no separate DISK_EXPAND job is needed on a fresh order.
616	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
617	    disk: "scsi0",
618	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
619	  });
620	
621	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
622	  // for a NAT server. If it cannot be proved, the readiness message says so
623	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
624	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
625	  // its IP, which is a worse outcome than a missing forward.
626	  let natError: Error | null = null;
627	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
628	
